#pragma once
static void testPatternBank(const File& root,Assets& assets){
    auto source=emptyProject();source.bpm=120;source.songMode=true;source.loop=false;source.patterns[0].name="A";source.patterns[0].lanes[7]={{0,.5,60,.8f,.7f,2}};
    for(int i=1;i<4;++i){Pattern p;p.name=String::charToString((juce_wchar)('A'+i));p.lanes.resize(source.tracks.size());p.lanes[7]={{0,.5,60+i*3,.8f}};source.patterns.push_back(p);}source.clips={{7,0,0,8},{7,3,8,16},{7,2,24,4}};source.activePattern=3;
    auto before=JSON::toString(projectToJson(source));Project output;PatternEditStats stats;
    expect(movePattern(source,3,0,output,&stats).wasOk()&&output.patterns[0].name=="D"&&output.patterns[1].name=="A"&&output.activePattern==0,"Move earlier reorders patterns while keeping the same active contents");
    expect(output.clips[0].pattern==1&&output.clips[1].pattern==0&&output.clips[2].pattern==3&&stats.movedFrom==3&&stats.movedTo==0&&stats.relinked==3,"Move earlier remaps each affected Playlist reference");
    expect(output.patterns[0].editorId==source.patterns[3].editorId&&output.patterns[1].lanes==source.patterns[0].lanes&&JSON::toString(projectToJson(source))==before,"reordering preserves session identity, notes and immutable source");
    expect(movePattern(source,0,3,output).wasOk()&&output.patterns[3].name=="A"&&output.activePattern==2&&output.clips[0].pattern==3&&output.clips[1].pattern==2,"Move later shifts intermediate references and the active index correctly");
    bool allMappings=true;for(int from=0;from<4;++from)for(int to=0;to<4;++to)if(from!=to){Project next;auto r=movePattern(source,from,to,next);allMappings&=r.wasOk();for(size_t i=0;i<source.clips.size();++i)allMappings&=next.patterns[(size_t)next.clips[i].pattern].editorId==source.patterns[(size_t)source.clips[i].pattern].editorId;allMappings&=next.patterns[(size_t)next.activePattern].editorId==source.patterns[(size_t)source.activePattern].editorId;}
    expect(allMappings,"all four-pattern move directions preserve active and clip identities");
    auto oldAudio=render(source,assets,root,70000,127),newAudio=render(output,assets,root,70000,512);float difference=0;for(int ch=0;ch<2;++ch)for(int i=0;i<70000;++i)difference=jmax(difference,std::abs(oldAudio.getSample(ch,i)-newAudio.getSample(ch,i)));expect(difference<.000001f&&oldAudio.getMagnitude(0,0,70000)>.001f,"bank reordering preserves actual Song audio across callback sizes");
    auto mixed=source;Clip audio{2,999,0,1};audio.audioPath="source.wav";audio.sourceOffset=.25;mixed.clips.push_back(audio);Clip automation{2,1,0,1};automation.automationTarget=0;automation.automationTrack=7;automation.points={{0,.2f,false},{1,.7f,true}};mixed.clips.push_back(automation);movePattern(mixed,0,3,output);
    expect(output.clips[3].pattern==999&&output.clips[3].sourceOffset==.25&&output.clips[4].pattern==1&&output.clips[4].automationTrack==7,"reorder ignores irrelevant audio and automation pattern fields");
    expect(patternUsage(mixed,1)==0&&patternUsage(mixed,0)==1&&patternUsage(mixed,3)==1,"pattern usage counts only ordinary references including repeated clips");
    expect(deleteUnusedPattern(mixed,1,output,&stats).wasOk()&&output.patterns.size()==3&&output.patterns[1].name=="C"&&output.activePattern==2&&stats.removed==1,"unused-pattern deletion removes one slot and remaps active selection");
    expect(output.clips[0].pattern==0&&output.clips[1].pattern==2&&output.clips[2].pattern==1&&output.clips[3].pattern==999&&output.clips[4].pattern==1,"deletion preserves ordinary clip meaning and unrelated audio/automation fields");
    expect(output.patterns[2].editorId==source.patterns[3].editorId&&output.patterns[1].lanes==source.patterns[2].lanes,"remaining pattern identities and complete note data survive deletion");
    deleteUnusedPattern(source,1,output);auto deletedAudio=render(output,assets,root,70000,511);difference=0;for(int ch=0;ch<2;++ch)for(int i=0;i<70000;++i)difference=jmax(difference,std::abs(oldAudio.getSample(ch,i)-deletedAudio.getSample(ch,i)));expect(difference<.000001f,"deleting an unused pattern leaves rendered Song audio unchanged");
    auto sentinel=JSON::toString(projectToJson(output));stats={{17},19,21,22,23};expect(deleteUnusedPattern(source,0,output,&stats).failed()&&JSON::toString(projectToJson(output))==sentinel&&stats.created==std::vector<int>{17}&&stats.removed==21&&stats.movedFrom==22,"used-pattern deletion fails atomically without changing stats");
    auto silent=source;silent.patterns[0].lanes[7].clear();silent.tracks[7].mute=true;expect(deleteUnusedPattern(silent,0,output).failed(),"even silent or muted Playlist references protect a pattern from deletion");
    auto single=emptyProject();expect(deleteUnusedPattern(single,0,output).failed(),"deleting the final pattern is rejected");expect(movePattern(source,0,0,output).failed()&&movePattern(source,-1,2,output).failed()&&movePattern(source,0,4,output).failed(),"no-op and out-of-bank moves are rejected without mutation");expect(deleteUnusedPattern(source,99,output).failed(),"stale delete index is rejected");
    auto active=source;active.clips.clear();active.activePattern=1;deleteUnusedPattern(active,1,output);expect(output.activePattern==1&&output.patterns[1].name=="C","deleting the active middle pattern chooses its successor");active.activePattern=3;deleteUnusedPattern(active,3,output);expect(output.activePattern==2&&output.patterns[2].name=="C","deleting the final active slot chooses its predecessor");active.activePattern=0;deleteUnusedPattern(active,2,output);expect(output.activePattern==0&&output.patterns[0].name=="A","deleting a later inactive slot retains active contents");
    auto full=source;while(full.patterns.size()<maxPatterns){Pattern p;p.name="Unused";p.lanes.resize(full.tracks.size());full.patterns.push_back(p);}expect(deleteUnusedPattern(full,31,output).wasOk()&&output.patterns.size()==31,"cleanup frees one slot in a full 32-pattern bank");Project unique;expect(makeClipPatternUnique(output,0,unique).wasOk()&&unique.patterns.size()==32,"a reclaimed slot is immediately usable for Make unique");
    auto corrupt=source;corrupt.clips[1].pattern=55;expect(movePattern(corrupt,0,1,output).failed()&&deleteUnusedPattern(corrupt,1,output).failed(),"invalid Playlist references block bank changes");
    auto identities=source;identities.patterns[1].editorId=identities.patterns[0].editorId;identities.patterns[2].editorId.clear();ensurePatternEditorIds(identities);std::set<String> seen;for(auto& p:identities.patterns)seen.insert(p.editorId);expect(seen.size()==identities.patterns.size()&&!seen.count(String()),"session identities repair duplicate copies and empty identifiers");auto copy=identities;ensurePatternEditorIds(identities);bool stable=true;for(size_t i=0;i<copy.patterns.size();++i)stable&=copy.patterns[i].editorId==identities.patterns[i].editorId;expect(stable,"valid session identities stay stable through copies and repeated publication");
    expect(patternIndexForEditorId(identities,identities.patterns[2].editorId)==2&&patternIndexForEditorId(identities,"absent")==-1&&patternIndexForEditorId(identities,{})==-1,"clipboard identity lookup rejects absent targets without falling back to indices");
    makeClipPatternUnique(identities,0,output);expect(output.patterns.back().editorId!=identities.patterns[0].editorId,"Make unique assigns a new identity to its independent pattern");
    auto json=projectToJson(identities);expect(!JSON::toString(json).contains(identities.patterns[0].editorId)&&(int)json["schema"]==projectSchema,"editor identities remain outside current-schema files and musical metadata");Project loaded;expect(projectFromJson(json,loaded).wasOk()&&loaded.patterns[0].editorId!=identities.patterns[0].editorId&&loaded.patterns[0].lanes==identities.patterns[0].lanes,"project loading starts fresh clipboard identities with identical musical contents");
    auto inPlace=source;expect(movePattern(inPlace,3,0,inPlace).wasOk()&&inPlace.patterns[0].name=="D"&&deleteUnusedPattern(inPlace,2,inPlace).wasOk()&&inPlace.patterns.size()==3,"bank operations safely support in-place source/output aliases");
}
